class WholeMapBlocksTest{public static void main(String[]args){for(int n:new int[]{32,256,1024,4096,16384}){var far=WholeMapBlocks.far(n);if(far.x()!=0||far.z()!=0||far.step()*far.grid()<n||far.grid()>512)throw new AssertionError("Far level omits map edge");for(double x:new double[]{-n,n*.5,n*2})for(double z:new double[]{-n,n*.5,n*2}){var near=WholeMapBlocks.middle(n,x,z);if(near.x()<0||near.z()<0||near.x()+near.grid()*near.step()>n||near.z()+near.grid()*near.step()>n||near.x()%near.step()!=0||near.z()%near.step()!=0)throw new AssertionError("Fine level leaves map or shifts off grid");}}System.out.println("PASS: whole-map block levels cover every map edge and keep finer terrain aligned and bounded for all camera positions");}}
